CREATE TYPE "CourseStatus" AS ENUM ('DRAFT','PUBLISHED','ARCHIVED');
CREATE TYPE "PaymentStatus" AS ENUM ('PENDING','PAID','FAILED','REFUNDED','CANCELLED');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"verifiedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Course" ("id" TEXT PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"title" TEXT NOT NULL,"eyebrow" TEXT NOT NULL,"description" TEXT NOT NULL,"longDescription" TEXT NOT NULL,"instructor" TEXT NOT NULL,"difficulty" TEXT NOT NULL,"duration" TEXT NOT NULL,"lessonCount" INTEGER NOT NULL,"priceCents" INTEGER NOT NULL,"currency" TEXT NOT NULL DEFAULT 'USD',"rating" DOUBLE PRECISION NOT NULL DEFAULT 0,"reviewCount" INTEGER NOT NULL DEFAULT 0,"image" TEXT NOT NULL,"accent" TEXT NOT NULL,"outcomes" TEXT[] NOT NULL,"requirements" TEXT[] NOT NULL,"status" "CourseStatus" NOT NULL DEFAULT 'DRAFT',"publishedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "CourseModule" ("id" TEXT PRIMARY KEY,"courseId" TEXT NOT NULL REFERENCES "Course"("id") ON DELETE CASCADE,"title" TEXT NOT NULL,"position" INTEGER NOT NULL,UNIQUE("courseId","position"));
CREATE TABLE "Lesson" ("id" TEXT PRIMARY KEY,"moduleId" TEXT NOT NULL REFERENCES "CourseModule"("id") ON DELETE CASCADE,"title" TEXT NOT NULL,"duration" TEXT NOT NULL,"position" INTEGER NOT NULL,"isPreview" BOOLEAN NOT NULL DEFAULT false,"videoAssetId" TEXT,"publishedAt" TIMESTAMP(3),UNIQUE("moduleId","position"));
CREATE TABLE "Purchase" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id"),"provider" TEXT NOT NULL,"providerSessionId" TEXT NOT NULL UNIQUE,"status" "PaymentStatus" NOT NULL DEFAULT 'PENDING',"amountCents" INTEGER NOT NULL,"currency" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"paidAt" TIMESTAMP(3));
CREATE TABLE "PurchaseItem" ("purchaseId" TEXT NOT NULL REFERENCES "Purchase"("id") ON DELETE CASCADE,"courseId" TEXT NOT NULL REFERENCES "Course"("id"),"priceCents" INTEGER NOT NULL,PRIMARY KEY("purchaseId","courseId"));
CREATE TABLE "Enrollment" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"courseId" TEXT NOT NULL REFERENCES "Course"("id"),"purchaseId" TEXT NOT NULL REFERENCES "Purchase"("id"),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("userId","courseId"));
CREATE TABLE "LessonProgress" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"lessonId" TEXT NOT NULL REFERENCES "Lesson"("id") ON DELETE CASCADE,"completedAt" TIMESTAMP(3),"positionSec" INTEGER NOT NULL DEFAULT 0,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("userId","lessonId"));
CREATE TABLE "LessonNote" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"lessonId" TEXT NOT NULL REFERENCES "Lesson"("id") ON DELETE CASCADE,"body" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("userId","lessonId"));
CREATE TABLE "PaymentTransaction" ("id" TEXT PRIMARY KEY,"purchaseId" TEXT NOT NULL REFERENCES "Purchase"("id") ON DELETE CASCADE,"eventId" TEXT NOT NULL UNIQUE,"fromStatus" "PaymentStatus","toStatus" "PaymentStatus" NOT NULL,"payloadHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "WebhookEvent" ("id" TEXT PRIMARY KEY,"provider" TEXT NOT NULL,"payloadHash" TEXT NOT NULL,"receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"processedAt" TIMESTAMP(3));
CREATE TABLE "ContactSubmission" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"topic" TEXT NOT NULL,"message" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "RateLimitBucket" ("key" TEXT PRIMARY KEY,"count" INTEGER NOT NULL,"resetAt" TIMESTAMP(3) NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "Course_status_publishedAt_idx" ON "Course"("status","publishedAt");
CREATE INDEX "Purchase_userId_status_idx" ON "Purchase"("userId","status");
CREATE INDEX "Enrollment_courseId_idx" ON "Enrollment"("courseId");
CREATE INDEX "WebhookEvent_provider_receivedAt_idx" ON "WebhookEvent"("provider","receivedAt");
CREATE INDEX "ContactSubmission_createdAt_idx" ON "ContactSubmission"("createdAt");
CREATE INDEX "RateLimitBucket_resetAt_idx" ON "RateLimitBucket"("resetAt");
